typedef unsigned int u_int;
typedef unsigned char u_char;
#define NULL 0

struct nglSortInfo
{
  u_int Type;
  union {
    float Dist;
    u_int Hash;
  };
};

struct nglScene
{
  nglScene* Parent;
  nglScene* NextSibling;
  nglScene* FirstChild;
  nglScene* LastChild;
  u_char Data[1008];
  void* OpaqueRenderList;
  void* TransRenderList;
  u_int OpaqueListCount, TransListCount;
  u_char Tail[160];
};

typedef void (*nglCustomNodeFn)( u_int*& Packet, void* Data );

enum
{
  NGLNODE_SCENE = 5,
};

extern nglScene nglDefaultScene;
extern nglScene* nglCurScene;
void* nglListAlloc( u_int Bytes, u_int Alignment = 4 );
void nglListAddNode( u_int Type, nglCustomNodeFn NodeFn, void* Data, nglSortInfo* SortInfo, u_char **Buf = 0 );
void nglVif1RenderSceneNode( u_int*& Packet, void* Param );
void* memcpy(void*, const void*, u_int);

__asm__(".equ nglDefaultScene, 0x004AB850");
__asm__(".equ nglCurScene, 0x004ABD04");
__asm__(".equ nglListAlloc__FUiUi, 0x00397C90");
__asm__(".equ nglListAddNode__FUiPFRPUiPv_vPvP11nglSortInfoPPUc, 0x00397CD0");
__asm__(".equ nglVif1RenderSceneNode__FRPUiPv, 0x00399520");

#define nglListNew( Type ) (Type*)nglListAlloc( sizeof(Type) )

nglScene *nglListBeginScene(nglSortInfo *SortInfo)
{
  nglScene* Scene;
  if ( !nglCurScene )
	Scene = &nglDefaultScene;
  else
  {
    // Add the new scene at the end of the current scene's child list.
    Scene = nglListNew( nglScene );
    if ( !Scene )
      return (nglScene *)0;
	if (!SortInfo)
	{
	  if ( nglCurScene->LastChild )
		nglCurScene->LastChild->NextSibling = Scene;
	  else
		nglCurScene->FirstChild = Scene;
	  nglCurScene->LastChild = Scene;
	}

    // Set up the scene based on nglDefaultScene (whose parameters can be set outside the render loop).
    memcpy( Scene, &nglDefaultScene, sizeof(nglScene) );
  }

  // Initialize the new scene's hierarchy linkage.
  Scene->Parent = nglCurScene;
  Scene->NextSibling = NULL;
  Scene->FirstChild = NULL;
  Scene->LastChild = NULL;

  // Initialize the new scene's bin structure.
  Scene->OpaqueRenderList = NULL;
  Scene->TransRenderList = NULL;
  Scene->OpaqueListCount = 0;
  Scene->TransListCount = 0;

  if (SortInfo)
    nglListAddNode( NGLNODE_SCENE, nglVif1RenderSceneNode, (void *)Scene, SortInfo );

  nglCurScene = Scene;

  return Scene;
}
